"use strict";
(()=>{
  const data=window.LEARNWITHUS_WORLD_CURRENCIES||[],search=document.getElementById('currencySearch'),region=document.getElementById('currencyRegion'),regionMap=document.getElementById('currencyRegionMap'),grid=document.getElementById('currencyGrid'),selected=document.getElementById('currencySelected'),count=document.getElementById('currencyCount'),challenge=document.getElementById('currencyChallenge'),prompt=document.getElementById('currencyPrompt'),choices=document.getElementById('currencyChoices'),feedback=document.getElementById('currencyFeedback'),next=document.getElementById('currencyNext');
  if(!grid)return;
  const speak=text=>{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.78;window.speechSynthesis.speak(u)};
  const flag=code=>{if(!/^[A-Z]{2}$/.test(code||''))return '🌐';return String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt(0)))};
  const regions=[...new Set(data.map(x=>x.region))].sort();
  regions.forEach(r=>{const o=document.createElement('option');o.value=r;o.textContent=r;region.append(o)});
  regionMap.innerHTML='<button type="button" class="currency-region-chip is-active" data-region="all">🌍 All regions</button>'+regions.map(r=>'<button type="button" class="currency-region-chip" data-region="'+r+'">'+({Asia:'🌏',Europe:'🌍',Africa:'🌍','North America':'🌎','South America':'🌎',Oceania:'🌏'}[r]||'🌐')+' '+r+'</button>').join('');
  const currencyText=x=>x.currencies.map(c=>c.name+' ('+c.code+')').join(' / ');
  function showSelected(x){if(!x){selected.innerHTML='<p>Choose a country below to see its currency details.</p>';return;}const text=currencyText(x);selected.innerHTML='<div class="currency-selected-flag" aria-hidden="true">'+flag(x.code)+'</div><div><p class="eyebrow">'+x.region+'</p><h3>'+x.country+'</h3><p class="currency-selected-name">'+text+'</p><p class="currency-selected-note">Currency codes help people identify money clearly across countries and banks.</p><button class="soft-button" id="hearCurrency" type="button">🔊 Hear currency</button></div>';document.getElementById('hearCurrency').onclick=()=>speak(x.country+' uses '+x.currencies.map(c=>c.name).join(' and ')+'.');}
  function setRegion(value){region.value=value;regionMap.querySelectorAll('[data-region]').forEach(b=>b.classList.toggle('is-active',b.dataset.region===value));render();}
  function render(){const q=search.value.trim().toLowerCase(),r=region.value;const shown=data.filter(x=>(r==='all'||x.region===r)&&(!q||x.country.toLowerCase().includes(q)||currencyText(x).toLowerCase().includes(q)));grid.replaceChildren();shown.forEach((x,i)=>{const b=document.createElement('button');b.type='button';b.className='currency-card currency-country-card';b.innerHTML='<span class="currency-flag" aria-hidden="true">'+flag(x.code)+'</span><strong>'+x.country+'</strong><span>'+currencyText(x)+'</span><small>'+x.region+'</small>';b.addEventListener('click',()=>{grid.querySelectorAll('.is-selected').forEach(el=>el.classList.remove('is-selected'));b.classList.add('is-selected');showSelected(x);});grid.append(b)});count.textContent=shown.length+' countr'+(shown.length===1?'y':'ies')+' shown.';if(shown.length&&!selected.dataset.initialized){showSelected(shown[0]);selected.dataset.initialized='1';}}
  search.addEventListener('input',render);region.addEventListener('change',()=>setRegion(region.value));regionMap.addEventListener('click',e=>{const b=e.target.closest('[data-region]');if(b)setRegion(b.dataset.region)});render();
  let current=null;const shuffle=a=>[...a].sort(()=>Math.random()-.5);
  function newChallenge(){current=data[Math.floor(Math.random()*data.length)];const answer=currencyText(current);const wrong=shuffle(data.filter(x=>x.country!==current.country).map(currencyText).filter((x,i,a)=>a.indexOf(x)===i&&x!==answer)).slice(0,3);prompt.innerHTML='<span class="currency-question-flag" aria-hidden="true">'+flag(current.code)+'</span><span>Which currency is used in <strong>'+current.country+'</strong>?</span>';choices.replaceChildren();feedback.textContent='';next.hidden=true;shuffle([answer,...wrong]).forEach(value=>{const b=document.createElement('button');b.type='button';b.textContent=value;b.addEventListener('click',()=>{choices.querySelectorAll('button').forEach(x=>x.disabled=true);const ok=value===answer;b.classList.add(ok?'correct':'wrong');const msg=ok?'Correct answer! It is '+answer+'.':'Wrong answer. The correct answer is '+answer+'.';feedback.textContent=msg;speak(msg);next.hidden=false;next.focus();},{once:true});choices.append(b)});}
  if(challenge){next.addEventListener('click',newChallenge);newChallenge();}
  window.LearnWithUs?.recordComplete('world-currencies.html');
})();